import BalanceInformations from "./components/BalanceInformations";
import Header from "./components/Header";
import Main from "./components/Main";
import ActionsSection from "./components/Actions";
import BalanceActions from "./components/BalanceActions";
import LoansActions from "./components/LoansActions";
import AccountActions from "./components/AccountActions";
import { useReducer } from "react";

const initalState = {
  isAccountOpen: false,
  balance: 0,
  loanBalance: 0,
  AccountActionLogs: [],
};

function reducer(state, action) {
  switch (action.type) {
    case "openAccount":
      const now = new Date();

      const formatted =
        now.getFullYear() +
        "-" +
        String(now.getMonth() + 1).padStart(2, "0") +
        "-" +
        String(now.getDate()).padStart(2, "0") +
        " " +
        String(now.getHours()).padStart(2, "0") +
        ":" +
        String(now.getMinutes()).padStart(2, "0") +
        ":" +
        String(now.getSeconds()).padStart(2, "0");

      return `${formatted} - account opened`;
      return {
        ...state,
        isAccountOpen: true,
        AccountActionLogs: [...state.AccountActionslogs, `{}`],
      };
    case "deposit":
      return { ...state, balance: state.balance + action.payload };
    case "withdrawal":
      if (state.balance < action.payload)
        throw new Error("Insufficient balance");
      return { ...state, balance: state.balance - action.payload };
    case "getLoan":
      return {
        ...state,
        balance: state.balance + action.payload,
        loanBalance: state.loanBalance - action.payload,
      };
    case "repayLoan":
      if (state.loanBalance < action.payload)
        throw new Error("loan payback can't be larger than the loan balance");
      return {
        ...state,
        balance: state.balance - action.payload,
        loanBalance: state.loanBalance + action.payload,
      };
    case "closeAccount":
      if (state.balance !== 0 || state.loanBalance !== 0)
        throw new Error(
          "both account balance and loan balance need to be zero to close the account",
        );
      return { ...state, isAccountOpen: false };
    default:
      throw new Error("Unknown reducer action");
  }
}

function App() {
  const [state, dispatch] = useReducer(reducer, initalState);

  return (
    <div className="app">
      <Header />
      <Main>
        <BalanceInformations
          balance={state.balance}
          loanBalance={state.loanBalance}
        />
        <ActionsSection>
          <BalanceActions dispatch={dispatch} />
          <LoansActions dispatch={dispatch} />
          <AccountActions dispatch={dispatch} />
        </ActionsSection>
      </Main>
    </div>
  );
}

export default App;
